#' An R6 class that represents a Task
#'
#' @family R6 classes
#' @export
Task <- R6::R6Class(
  "Task",
  public = list(
    #' @field connect The Connect instance.
    connect = NULL,
    #' @field task The task.
    task = NULL,
    #' @field data The task data.
    data = NULL,
    #' @description Initialize this task.
    #' @param connect The `Connect` instance.
    #' @param task The task data.
    initialize = function(connect, task) {
      validate_R6_class(connect, "Connect")
      self$connect <- connect
      # TODO: need to validate task (needs task_id)
      if ("id" %in% names(task) && !"task_id" %in% names(task)) {
        # deal with different task interfaces on Connect
        task$task_id <- task$id
      }
      self$task <- task
    },
    #' @description Return the underlying task.
    get_task = function() {
      self$task
    },
    #' @description Set the data.
    #' @param data The data.
    add_data = function(data) {
      self$data <- data
      invisible(self)
    },
    #' @description Get the data.
    get_data = function() {
      self$data
    },
    #' @description Print this object.
    #' @param ... Unused.
    print = function(...) {
      cat("Posit Connect Task: \n")
      cat("  Task ID: ", self$get_task()$task_id, "\n", sep = "")
      cat("\n")
      invisible(self)
    }
  )
)

#'
#' @param task A Task object
#' @param wait The interval to wait between polling
#' @param callback A function to be called for each message received. Set to NULL for no callback
#'
#' @return Task The Task object that was input
#'
#' @family deployment functions
#' @export
poll_task <- function(task, wait = 1, callback = message) {
  validate_R6_class(task, c("Task", "ContentTask", "VariantTask"))
  con <- task$connect

  all_task_data <- list()

  finished <- FALSE
  code <- -1
  first <- 0
  while (!finished) {
    task_data <- con$task(task$get_task()$task_id, wait = wait, first = first)
    finished <- task_data[["finished"]]
    code <- task_data[["code"]]
    first <- task_data[["last"]]

    if (!is.null(callback)) {
      lapply(task_data[["output"]], callback)
    }
    all_task_data <- c(all_task_data, task_data[["output"]])
  }

  if (code != 0) {
    msg <- task_data[["error"]]
    # print the logs if there is no callback
    if (is.null(callback)) {
      lapply(all_task_data, message)
    }
    stop(msg)
  }
  if (!is.null(task_data[["result"]])) {
    task$add_data(task_data[["result"]])
  }
  task
}

run_response = self.runs_start(
    command, is_direct, commit_id, title, tier, publish_api_endpoint
)
run_id = run_response["runId"]

poll_start = time.time()
current_retry_count = 0
while True:
    try:
        run_info = self.get_run_info(run_id)
        if run_info is None:
            raise exceptions.RunNotFoundException(
                f"Tried to access nonexistent run id {run_id}"
            )
        current_retry_count = 0
    except (
        requests.exceptions.RequestException,
        exceptions.RunNotFoundException,
    ) as e:
        current_retry_count += 1
        self.log.warning(f"Failed to get run info for runId: {run_id} : {e}")
        if current_retry_count > retry_count:
            raise Exception(
                f"Cannot get run info, max retry {retry_count} exceeded"
            ) from None
        else:
            self.log.info(
                f"Retrying ({current_retry_count}/{retry_count}) getting run info ..."
            )
            time.sleep(poll_freq)
            continue

    elapsed_time = time.time() - poll_start

    if elapsed_time >= max_poll_time:
        raise Exception(f"Run exceeded maximum time of {max_poll_time} seconds")

    output_commit_id = run_info.get("outputCommitId")
    if not output_commit_id:
        time.sleep(poll_freq)
        continue

    # once task has finished running check to see if it was successful
    else:
        stdout_msg = self.get_run_log(run_id=run_id, include_setup_log=False)

        if run_info["status"] != "Succeeded":
            self.process_log(stdout_msg)
            raise exceptions.RunFailedException(
                f"Remote run {run_id} finished but did not succeed."
            )

        break

return run_response

def run_workflow_definition(cls, name, prompts=None):
    """Runs specific Workflow Processes Definitions.

    Parameters
    ----------
    name : str
        Name or ID of an enabled workflow to execute
    prompts : dict, optional
        Input values to provide for the initial workflow prompts.  Should be
        specified as name:value pairs.

    Returns
    -------
    RestObj
        The executing workflow

    """
    workflow = cls._find_specific_workflow(name)
    if workflow is None:
        raise ValueError("No Workflow enabled for %s name or id." % name)

    if prompts is None:
        return cls.post(
            "/processes?definitionId=" + workflow["id"],
            headers={"Content-Type": "application/vnd.sas.workflow.variables+json"},
        )
    if isinstance(prompts, dict):
        variables = []

        # For each prompt defined in the workflow, check if a value was provided.
        for prompt in workflow.prompts:
            if prompt["variableName"] in prompts:
                name = prompt["variableName"]
                value = prompts[name]

                if type(value) == datetime.datetime:
                    # NOTE: do not use isinstance() to compare types as
                    # datetime.date will also evaluate as True.

                    # Explicitly convert to local time zone if not set.
                    if value.tzinfo is None:
                        try:
                            value = value.astimezone()
                        except OSError:
                            # On Windows pre-1970 dates will cause an issue.
                            # See https://bugs.python.org/issue36759
                            pass

                    if value.tzinfo is None:
                        # Failed to convert to local time.  Have to just assume it's UTC.
                        # Example: 2023-01-25T13:49:40.726162Z
                        value = value.isoformat() + "Z"
                    else:
                        # Example: 2023-01-25T13:49:40.726162-05:00
                        value = value.isoformat()

                variables.append(
                    {
                        "name": name,
                        "value": value,
                        "scope": "local",
                        "type": prompt["variableType"],
                        "version": prompt["version"],
                    }
                )

        return cls.post(
            "/processes?definitionId=" + workflow["id"],
            json={"variables": variables},
            headers={"Content-Type": "application/vnd.sas.workflow.variables+json"},
